-- Calumet Farm Kentucky Straight Bourbon (calumetbourbon.com, Bowling Green KY; the farm's own site calumetfarm.com carries no bourbon) importer, applied 2026-10-12. Order: maker row, part1, maker-declared discontinued, inserts.
update cellar.makers set website = coalesce(website, 'https://www.calumetbourbon.com'), country = coalesce(country, 'US') where id = 'b7319ada-bc44-438d-bfec-79f9f9158105';
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://images.squarespace-cdn.com/content/v1/5efa386f0fb20272eee20ede/bcd5f90c-b321-430c-b301-37bf16bdf67a/Calumet+Farm+16+Year+Old+Bourbon+-+Learn+More'), producer = coalesce(producer, 'Calumet Farm'), producer_id = coalesce(producer_id, 'b7319ada-bc44-438d-bfec-79f9f9158105'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.calumetbourbon.com/16-year-old-citation', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'allocated'::cellar.rarity) where id = '65abf120-cfe1-4cd9-970b-17bd0a5ba2a2' and facts_verified_at is null;
update cellar.products set mash_style = 'traditional', mash_bill = '74% Corn, 18% Rye, 8% Malted Barley', producer = coalesce(producer, 'Calumet Farm'), producer_id = coalesce(producer_id, 'b7319ada-bc44-438d-bfec-79f9f9158105'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.calumetbourbon.com/10-year-old-bull-lea', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '99370cba-178d-435c-a8d0-997cf164f2ec' and facts_verified_at is null;
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://images.squarespace-cdn.com/content/v1/5efa386f0fb20272eee20ede/21d705ae-f673-4374-92a8-950789611fb2/CA-SmallBatch-Bourbon-17+and+7+Year+Old'), producer = coalesce(producer, 'Calumet Farm'), producer_id = coalesce(producer_id, 'b7319ada-bc44-438d-bfec-79f9f9158105'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.calumetbourbon.com/smallbatch', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '3b1aefe5-f4c8-46d6-a9b2-bf60eee089e6' and facts_verified_at is null;
update cellar.products set mash_bill = '74% Corn, 18% Rye, 8% Malted Barley', name = 'Calumet Farm 14 Year', expression = '14 Year', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Calumet Farm')) a), producer = coalesce(producer, 'Calumet Farm'), producer_id = coalesce(producer_id, 'b7319ada-bc44-438d-bfec-79f9f9158105'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.calumetbourbon.com/14yo-singlerackblack-bti-gold', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity) where id = 'cee2d004-7691-4a7d-a911-08ae28051ca4' and facts_verified_at is null;
update cellar.products set name = 'Calumet Farm 12 Year Single Rack Black', expression = '12 Year Single Rack Black', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Calumet Farm Single Rack Black')) a), producer = coalesce(producer, 'Calumet Farm'), producer_id = coalesce(producer_id, 'b7319ada-bc44-438d-bfec-79f9f9158105'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.calumetbourbon.com/12yo-singlerackblack', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity) where id = 'e7f5521d-034e-4134-8d7a-fdedf2d4f95d' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('65abf120-cfe1-4cd9-970b-17bd0a5ba2a2', '99370cba-178d-435c-a8d0-997cf164f2ec', '3b1aefe5-f4c8-46d6-a9b2-bf60eee089e6', 'cee2d004-7691-4a7d-a911-08ae28051ca4', 'e7f5521d-034e-4134-8d7a-fdedf2d4f95d');
-- The maker's own pages mark these two "Out to pasture - Discontinued" (14 Year Single Rack Black, 12 Year Single Rack Black). The writer resets discontinued = false on a matched row, so set it here.
update cellar.products set discontinued = true where id in ('cee2d004-7691-4a7d-a911-08ae28051ca4', 'e7f5521d-034e-4134-8d7a-fdedf2d4f95d') and facts_verified_at is null;
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Calumet Farm 15 Year","rar":"allocated","f":"Calumet Farm","x":"15 Year","p":105.0,"ay":15.0,"al":"15 yr","nas":false,"et":"standard","ms":"traditional","mb":"74% Corn, 18% Rye, 8% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Calumet Farm 15 Year Old","Calumet Farm 15 Year Old Single Rack Black"],"img":"https://images.squarespace-cdn.com/content/v1/5efa386f0fb20272eee20ede/1617374994607-VTA781K9F9M14253C3LD/i-CAsrb15-web-Hero-wAgeLockUp-TightCrop-1122x1070-v1.png","u":"https://www.calumetbourbon.com/15-year-old-whirlaway","pr":"Calumet Farm","mk":"b7319ada-bc44-438d-bfec-79f9f9158105"},{"n":"Calumet Farm 12 Year","rar":"shelf","f":"Calumet Farm","x":"12 Year","p":102.0,"ay":12.0,"al":"12 yr","nas":false,"et":"standard","ms":"traditional","mb":"74% Corn, 18% Rye, 8% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Calumet Farm 12 Year Old","Calumet Farm 12 Year Old Bourbon"],"img":null,"u":"https://www.calumetbourbon.com/12-year-old","pr":"Calumet Farm","mk":"b7319ada-bc44-438d-bfec-79f9f9158105"},{"n":"Calumet Farm 8 Year","rar":"shelf","f":"Calumet Farm","x":"8 Year","p":90.0,"ay":8.0,"al":"8 yr","nas":false,"et":"standard","ms":"traditional","mb":"74% Corn, 18% Rye, 8% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Calumet Farm 8 Year Old"],"img":"https://images.squarespace-cdn.com/content/v1/5efa386f0fb20272eee20ede/12077378-4e3e-42c6-90d2-81793375f65e/Calumet+Farm+8+Year+Old+Kentucky+Straight+Bourbon","u":"https://www.calumetbourbon.com/8yo","pr":"Calumet Farm","mk":"b7319ada-bc44-438d-bfec-79f9f9158105"},{"n":"Calumet Farm Centennial Bottled in Bond","rar":"limited","f":"Calumet Farm","x":"Centennial Bottled in Bond","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["Calumet Farm Bottled in Bond Centennial Release"],"img":null,"u":"https://www.calumetbourbon.com/centennial-bottled-in-bond","pr":"Calumet Farm","mk":"b7319ada-bc44-438d-bfec-79f9f9158105"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
